using namespace std;

int f(int x)
{
    int res = 0;
    while(x != 0)
    {
        res += x % 10;
        x /= 10;
    }
    return res;
}

void solve()
{
    string s;
    cin >> s;
    int n = s.size();
    if(n == 1)
    {
        cout << s << "\n";
        return;
    }
    vector<int> cnt(10);
    int sum_digits = 0;
    for(auto x : s) 
    {
        cnt[x - '0']++;
        sum_digits += x - '0';
    }
    for(int x = 1; x <= n * 9; x++)
    {
        int nx = x;
        string sx = to_string(nx);
        while(nx > 9)
        {
            nx = f(nx);
            sx += to_string(nx);    
        }
        //cout << x << " " << sx << endl;               
        vector<int> need_cnt(10);
        int sum_digits_x = 0;
        for(auto y : sx)
        {
            need_cnt[y - '0']++;
            sum_digits_x += y - '0';
        }
        bool can = true;
        for(int i = 0; i <= 9; i++)
            if(need_cnt[i] > cnt[i]) can = false;
        if(sum_digits - sum_digits_x != x)
            can = false;
        if(can)
        {
            string res = "";
            for(int i = 9; i >= 0; i--)
            {
                for(int j = 0; j < cnt[i] - need_cnt[i]; j++)
                    res.push_back(char('0' + i));
            }
            res += sx;
            cout << res << endl;
            return;
        }
    }
}

int main()
{
    ios_base::sync_with_stdio(0);
    cin.tie(0);
    int t;
    cin >> t;
    for(int i = 0; i < t; i++)
        solve();
    return 0;
}

