const int MOD = 998'244'353;

int add(int a, int b) {
	a += b;
	while (a >= MOD)
		a -= MOD;
	while (a < 0)
		a += MOD;
	return a;
}
int mul(int a, int b) {
	return a * 1ll * b % MOD;
}
int binPow(int a, int k) {
	int ans = 1;
	while (k > 0) {
		if (k & 1)
			ans = mul(ans, a);
		a = mul(a, a);
		k >>= 1;
	}
	return ans;
}

int n, m;
vector<int> a, k;

inline bool read() {
	if(!(cin >> n >> m))
		return false;
	a.resize(n);
	fore (i, 0, n)
		cin >> a[i];
	k.resize(m);
	fore (i, 0, m)
		cin >> k[i];
	return true;
}

inline void solve() {
	vector<int> lf(n, -1), rg(n, n);
	vector<int> st;
	fore (i, 0, n) {
		while (!st.empty() && a[st.back()] > a[i])
			st.pop_back();
		if (!st.empty())
			lf[i] = st.back();
		st.push_back(i);
	}
	st.clear();
	for (int i = n - 1; i >= 0; i--) {
		while (!st.empty() && a[st.back()] >= a[i])
			st.pop_back();
		if (!st.empty())
			rg[i] = st.back();
		st.push_back(i);
	}

	int commonSum = 0;
	vector<int> la(m + 1), lk(m + 1), ra(m + 1), rk(m + 1);

	//[l, r)
	auto addSeg = [](vector<int> &pS, int l, int r, int val) {
		pS[l] = add(pS[l], val);
		pS[r] = add(pS[r], -val);
	};

	fore (i, 0, n) {
		int cnt = mul(i - lf[i], rg[i] - i);
		int rem = add(mul(i + 1, n - i), -cnt);
		int ia = binPow(a[i], MOD - 2);
		commonSum = add(commonSum, mul(rem, ia));

		int p = lower_bound(k.begin(), k.end(), a[i]) - k.begin();
		addSeg(la, 0, p, mul(cnt, ia));
		addSeg(lk, 0, p, mul(cnt, ia));
		addSeg(ra, p, m, cnt);
		addSeg(rk, p, m, mul(cnt, add(2, -a[i])));
	}
	fore (i, 0, m) {
		la[i + 1] = add(la[i + 1], la[i]);
		lk[i + 1] = add(lk[i + 1], lk[i]);
		ra[i + 1] = add(ra[i + 1], ra[i]);
		rk[i + 1] = add(rk[i + 1], rk[i]);
	}

	fore (i, 0, m) {
		int ans = commonSum;
		ans = add(ans, mul(add(la[i], ra[i]), k[i]));
		ans = add(ans, add(lk[i], rk[i]));
		cout << ans << '\n';
	}
}

